int trap_rain_water(int height[],int size){int left;int right;int left_max;int right_max;int water;left=0;right=size-1;left_max=0;right_max=0;water=0;while(left<right){if(height[left]<height[right]){if(height[left]>=left_max)left_max=height[left];else water=water+left_max-height[left];left=left+1;}else{if(height[right]>=right_max)right_max=height[right];else water=water+right_max-height[right];right=right-1;}}return water;}
int main(void){int a[12]={0,1,0,2,1,0,1,3,2,1,2,1};int b[6]={4,2,0,3,2,5};if(trap_rain_water(a,12)!=6)return 1;if(trap_rain_water(b,6)!=9)return 2;return 42;}
